(()=>{'use strict';
const $=s=>document.querySelector(s),E=agraxQuotes.esc,Q=agraxQuotes,M=agraxDashboardData,A=window.agraxAccount;
const cities=['New York','Chicago','Los Angeles','Philadelphia','Miami','Boston','Atlanta','Baltimore','Detroit','Columbia','Asheville'];
const cats={fruits:'Fruit',vegetables:'Vegetables',onions_potatoes:'Onions & potatoes',nuts:'Nuts'};
const paths={home:'M3 10 12 3l9 7v11h-6v-7H9v7H3Z',explore:'M4 20V10m8 10V4m8 16v-7',reports:'M6 3h9l4 4v14H6ZM14 3v5h5M9 12h7M9 16h7',email:'M3 5h18v14H3ZM3 5l9 7 9-7',saved:'M6 3h12v18l-6-4-6 4Z'};
const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.explore}"/></svg>`;
const snapshot=window.AGX_SNAPSHOT||{rows:[],histories:{}};const archived=new Map(),archiveMisses=new Set();let all=M.latest(snapshot.rows),route={},page=0,sort='name',direction=1,filter={},historyDays=90,renderId=0;
const historyCache=new Map(),updates=new Map(),failures=new Set(),historyPromises=new Map();
const url=(view,params={})=>'/?'+new URLSearchParams({view,...Object.fromEntries(Object.entries(params).filter(([,v])=>v!==''&&v!=null))});
const money=v=>M.number(v)===null?'—':'$'+Number(v).toFixed(2);
const range=r=>r.price_low==null&&r.price_high==null?'Not quoted':r.price_low==null?money(r.price_high)+' (high)':r.price_high==null?money(r.price_low)+' (low)':r.price_low===r.price_high?money(r.price_low):money(r.price_low)+'–'+money(r.price_high);
const date=v=>/^\d{4}-\d{2}-\d{2}$/.test(v||'')?new Date(v+'T12:00:00Z').toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric',timeZone:'UTC'}):'Not supplied';
const latest=rs=>rs.map(r=>r.report_date).sort().at(-1),unique=rs=>[...new Set(rs.filter(Boolean))];
const label=r=>Q.unique([r.variety,r.properties,r.organic?'Organic':'',r.origin,r.package,r.size]);
const empty=(title,text,link='')=>`<div class="empty"><h2>${title}</h2><p>${text}</p>${link}</div>`;
const btn=(text,href,cls='')=>`<a class="btn ${cls}" href="${E(href)}">${text}</a>`;
const head=(tag,title,sub,action='')=>`<div class="page-head"><div><span class="eyebrow">${tag}</span><h1>${E(title)}</h1><p>${sub}</p></div>${action}</div>`;
const crumbs=items=>`<nav class="breadcrumbs" aria-label="Breadcrumb">${items.map(([name,href])=>href?`<a href="${E(href)}">${E(name)}</a>`:`<span>${E(name)}</span>`).join('<span aria-hidden="true">/</span>')}</nav>`;
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');setTimeout(()=>$('#toast').classList.remove('visible'),3500);}
function nav(){const v=['product','quote','market'].includes(route.view)?'explore':route.view==='report'?'reports':route.view==='manage'?'email':route.view;$('#navigation').innerHTML=Object.entries({home:'Overview',explore:'Explore prices',reports:'Report library',email:'Daily email reports',saved:'Saved products'}).map(([k,t])=>`<a href="${url(k)}" class="${v===k?'active':''}" ${v===k?'aria-current="page"':''}>${icon(k)}<span>${t}</span></a>`).join('');$('#account-button').textContent=A?.user()?'Account':'Sign in';}
function go(view,params={},replace=false){history[replace?'replaceState':'pushState'](null,'',url(view,params));page=0;filter={};render();window.scrollTo(0,0);}
function render(){renderId++;route=AgraXRoutes.resolve(location.pathname,location.search,location.hash);if(route.view==='product')filter=Object.fromEntries(['market','variety','origin','package','size'].filter(k=>route['f_'+k]!=null).map(k=>[k,route['f_'+k]==='__all__'?'':route['f_'+k]]));document.body.classList.remove('menu-open');$('#mobile-menu').setAttribute('aria-expanded','false');nav();document.title=({home:'Know your market',explore:'Explore prices',product:route.c,quote:route.c||'Quote details',reports:'Report library',report:'Market report',email:'Daily email reports',saved:'Saved products',about:'About AgraX',privacy:'Privacy policy',manage:'Report preferences'}[route.view]||'AgraX')+' · AgraX';({home,explore,product,quote,reports,report,email,saved,about,privacy,manage}[route.view]||notFound)();A?.ready.then(()=>window.agraxAccountUI?.mount());}
function home(){const total=unique(all.map(r=>r.commodity)).length;$('#content').innerHTML=`<section class="hero"><div class="hero-copy"><span class="eyebrow">A CLEARER VIEW OF PRODUCE</span><h1>Commodity Data<br><em>for Produce Markets</em></h1><p>The produce market, made easier to navigate. Explore wholesale prices, compare markets, and follow the products that matter to you.</p>${btn('Explore market prices <span>↗</span>',url('explore'),'dark')}</div><div class="hero-image"><img src="/assets/account-warehouse.jpg" alt="Workers and fresh produce at a wholesale market warehouse" fetchpriority="high" style="object-position:center 30%"><div class="image-caption"><div><small>FROM THE SOURCE. FOR YOUR BUSINESS.</small><strong>USDA market reports, made useful.</strong></div><a href="${url('about')}" aria-label="Learn about our data">↗</a></div></div></section><section class="market-strip" aria-label="Explore terminal markets">${cities.slice(0,4).map(c=>`<a class="market-tile" href="${E(url('explore',{market:c}))}"><div>${c}<span>↗</span></div><small>${unique(all.filter(r=>r.market===c).map(r=>r.commodity)).length} commodities · ${E(date(latest(all.filter(r=>r.market===c))))}</small></a>`).join('')}</section><section class="email-band"><div class="email-symbol">${icon('email')}</div><div><h2>Your markets. In your inbox.</h2><p>Choose your reports. Get them by email after publication. Free, with no account required.</p></div>${btn('Get daily report emails <span>↗</span>',url('email'))}</section><div class="home-grid"><section class="panel"><div class="section-bar"><h2>Find your product</h2><span class="small-label">${total}</span></div>${Object.entries(cats).map(([k,v],i)=>`<a class="link-row" href="${url('explore',{category:k})}"><div class="category-row"><span class="category-dot">${['◒','✳','◍','◇'][i]}</span><div><strong>${v}</strong><small>${unique(all.filter(r=>r.commodity_type===k).map(r=>r.commodity)).length} commodities</small></div></div><span>↗</span></a>`).join('')}</section><section class="panel"><div class="section-bar"><h2>Market reports</h2><a href="${url('reports')}">View all ↗</a></div>${cities.slice(0,4).map(c=>`<a class="link-row" href="${E(url('reports',{market:c}))}"><div><strong>${c}</strong><small>${E(date(latest(all.filter(r=>r.market===c))))}</small></div><span>${unique(all.filter(r=>r.market===c).map(r=>r.commodity_type)).length} reports ↗</span></a>`).join('')}</section><section class="panel"><div class="section-bar"><h2>Start exploring</h2></div>${['Avocados','Apples','Tomatoes','Potatoes'].map(n=>`<a class="link-row" href="${url('product',{c:n})}"><div><strong>${n}</strong><small>${unique(all.filter(r=>r.commodity===n).map(r=>r.market)).length} terminal markets</small></div><span>↗</span></a>`).join('')}</section></div><section class="photo-band"><img src="/assets/agriculture-fields-hero-v1.jpg" alt="Green agricultural fields under an open sky" loading="lazy"><div><span class="eyebrow">BUILT FOR THE PRODUCE BUSINESS</span><h2>Less digging.<br>More understanding.</h2><p>Variety, origin, pack, and size stay with every quote. So you can compare the products you actually buy.</p><a class="btn text" href="${url('about')}">How AgraX works ↗</a></div></section><p class="notice">Prices reflect dated USDA reports, not live trading. Each market’s publication date is shown above.</p>`;}
function groups(rs){const g=new Map();rs.forEach(r=>{if(!g.has(r.commodity))g.set(r.commodity,[]);g.get(r.commodity).push(r);});return [...g];}
function filteredBase(){return all.filter(r=>(!route.market||r.market===route.market)&&(!route.category||r.commodity_type===route.category)&&(!route.origin||r.origin===route.origin)&&(!route.q||[r.commodity,r.variety,r.origin,r.market].some(v=>String(v||'').toLowerCase().includes(route.q.toLowerCase()))));}
let exploreSearchTimer;
matchMedia('(min-width:601px)').addEventListener('change',e=>{const panel=$('.explore-extra');if(panel)panel.open=e.matches;const productPanel=$('.product-refine');if(productPanel)productPanel.open=e.matches;});
function explore(){clearTimeout(exploreSearchTimer);const rs=filteredBase();let gs=groups(rs);gs.sort((a,b)=>direction*(sort==='markets'?unique(a[1].map(r=>r.market)).length-unique(b[1].map(r=>r.market)).length:sort==='date'?latest(a[1]).localeCompare(latest(b[1])):a[0].localeCompare(b[0])));page=Math.min(page,Math.max(0,Math.ceil(gs.length/30)-1));$('#content').innerHTML='<div class="explore-view">'+head('PRICE EXPLORER',route.market||'Explore prices','Start with a commodity. Then choose the variety, origin, package, and market.',btn('Daily report emails ↗',url('email'),'light'))+`<div class="chips">${[['','All produce'],...Object.entries(cats)].map(([k,v])=>`<a class="chip ${route.category===k||(!route.category&&!k)?'active':''}" href="${E(url('explore',{...route,view:undefined,category:k}))}">${v}</a>`).join('')}</div><form class="toolbar" id="explore-form"><label class="explore-search"><span>Search commodities</span><input name="q" type="search" placeholder="Search commodities" value="${E(route.q||'')}"></label><label class="explore-market"><span>Market</span><select name="market"><option value="">All markets</option>${cities.map(c=>`<option ${route.market===c?'selected':''}>${c}</option>`).join('')}</select></label><details class="explore-extra"><summary>Filters <span>(${route.origin?1:0})</span><svg viewBox="0 0 20 20" aria-hidden="true"><path d="M3 5h14M6 10h8M8 15h4"/></svg></summary><div class="explore-extra-panel"><label>Origin<select name="origin"><option value="">All origins</option>${unique(all.filter(r=>!route.market||r.market===route.market).map(r=>r.origin)).sort().map(o=>`<option ${o===route.origin?'selected':''}>${E(o)}</option>`).join('')}</select></label><button type="button" id="clear-origin">Clear filter</button></div></details><button class="btn light explore-apply" type="submit">Apply</button></form><div class="explore-results-bar"><div class="explore-count" role="status">${gs.length} ${gs.length===1?'commodity':'commodities'}</div><div class="explore-output-actions"><button id="explore-copy-link">Copy link</button><button class="btn light" id="explore-export">Export prices ↗</button></div></div><div class="table-box"><table class="data-table"><thead><tr><th><button data-sort="name">Commodity ${sort==='name'?(direction===1?'↑':'↓'):'↕'}</button></th><th><button data-sort="markets">Markets ↕</button></th><th class="hide-mobile">Origins</th><th><button data-sort="date">Latest report ↕</button></th><th></th></tr></thead><tbody>${gs.slice(page*30,page*30+30).map(([n,list])=>`<tr><td><a href="${E(url('product',{c:n,market:route.market}))}">${E(n)}</a><small>${list.length} reported specifications</small></td><td>${unique(list.map(r=>r.market)).length}</td><td class="hide-mobile">${E(unique(list.map(r=>r.origin)).slice(0,3).join(', '))}${unique(list.map(r=>r.origin)).length>3?' + more':''}</td><td class="numeric">${E(date(latest(list)))}</td><td><a href="${E(url('product',{c:n,market:route.market}))}" aria-label="View ${E(n)}">↗</a></td></tr>`).join('')}</tbody></table>${!gs.length?empty('No matching products','Try another term or clear your filters.',btn('Reset filters',url('explore'),'light')):''}</div>${pager(gs.length)}<p class="notice">Prices are reported per package. Dates may differ by market and report category.${route.market?` <button id="refresh-market">Check for newer ${E(route.market)} reports</button>`:''}</p></div>`;$('#explore-copy-link').onclick=copyExplorerLink;$('#explore-export').onclick=()=>openExplorerExport(rs,gs.slice(page*30,page*30+30).flatMap(([,rows])=>rows));const form=$('#explore-form');$('.explore-extra').open=matchMedia('(min-width:601px)').matches;function applyFilters(keepSearch=false){clearTimeout(exploreSearchTimer);const p=Object.fromEntries(new FormData(form));const cursor=form.elements.q.selectionStart;history.replaceState(null,'',url('explore',{...p,category:route.category}));page=0;render();if(keepSearch){const input=$('#explore-form input[name=q]');input.focus({preventScroll:true});if(cursor!=null)input.setSelectionRange(cursor,cursor);}}form.onsubmit=e=>{e.preventDefault();applyFilters();};form.elements.q.oninput=()=>{exploreSearchTimer=setTimeout(()=>{if(form.isConnected)applyFilters(true);},180);};form.elements.market.onchange=()=>{form.elements.origin.value='';applyFilters();};form.elements.origin.onchange=()=>applyFilters();$('#clear-origin').onclick=()=>{form.elements.origin.value='';applyFilters();};document.querySelectorAll('[data-sort]').forEach(b=>b.onclick=()=>{direction=sort===b.dataset.sort?-direction:1;sort=b.dataset.sort;explore();});bindPager(explore);$('#refresh-market')?.addEventListener('click',()=>refresh(route.market));}
function exportCSV(rows){
 const fields=['commodity','market','report_date','commodity_type','variety','origin','package','size','grade','organic','properties','quality','quality_note','condition','appearance','notes','price_notes','price_qualifier','price_low','price_high','price_mostly_low','price_mostly_high','source_report','row_hash'];
 const cell=v=>{let text=v==null?'':String(v);if(/^[\s]*[=+@-]/.test(text)&&typeof v!=='number')text="'"+text;return '"'+text.replaceAll('"','""')+'"';};
 return '\ufeff'+[fields.map(cell).join(','),...rows.map(r=>fields.map(f=>cell(r[f])).join(','))].join('\r\n');
}
async function copyExplorerLink(){
 const link='https://www.agra-x.com'+url('explore',{market:route.market,category:route.category,origin:route.origin,q:route.q});
 try{await navigator.clipboard.writeText(link);toast('Link copied. Opens with your current search and filters.');}
 catch{const dialog=document.createElement('dialog');dialog.id='copy-link-dialog';dialog.setAttribute('aria-label','Copy link');dialog.innerHTML=`<form method="dialog"><h2>Copy link</h2><p class="notice">Opens with your current search and filters.</p><input aria-label="Link to these prices" readonly value="${E(link)}"><button class="btn light">Done</button></form>`;document.body.append(dialog);dialog.addEventListener('close',()=>dialog.remove(),{once:true});dialog.showModal();dialog.querySelector('input').select();}
}
function openExplorerExport(filtered,pageRows){
 const description=[route.market||'All markets',cats[route.category]||'All produce',route.origin,route.q?'Search: '+route.q:''].filter(Boolean).join(' · ');
 const dialog=document.createElement('dialog');dialog.id='explorer-export-dialog';dialog.setAttribute('aria-labelledby','export-title');
 dialog.innerHTML=`<div class="print-dialog-heading"><h2 id="export-title">Export prices</h2><button id="close-export" aria-label="Close export options">✕</button></div><p class="notice">${E(description)}</p><fieldset class="export-scope"><legend>What to export</legend><label><input type="radio" name="export-scope" value="filtered" checked> All matching results <small>${groups(filtered).length} commodities · ${filtered.length} prices</small></label><label><input type="radio" name="export-scope" value="page"> This page only <small>${groups(pageRows).length} commodities · ${pageRows.length} prices</small></label><label><input type="radio" name="export-scope" value="report"> An entire market report</label></fieldset><div id="export-report-fields" hidden><label>Market<select id="export-market">${cities.map(c=>`<option ${c===route.market?'selected':''}>${E(c)}</option>`).join('')}</select></label><label>Category<select id="export-category">${Object.entries(cats).map(([k,v])=>`<option value="${k}" ${k===route.category?'selected':''}>${E(v)}</option>`).join('')}</select></label><p class="notice" id="export-report-date"></p></div><p class="notice" id="export-summary" role="status"></p><p class="notice">Exports include detailed quotes, report dates, package units, and USDA sources. Prices may have different publication dates.</p><div class="print-dialog-actions"><button class="btn light" id="export-csv">Download CSV</button><button class="btn" id="export-print">Print / Save PDF</button></div><p class="notice" id="export-status" role="status"></p>`;
 document.body.append(dialog);
 const scope=()=>dialog.querySelector('[name="export-scope"]:checked').value;
 function rows(){if(scope()==='filtered')return filtered;if(scope()==='page')return pageRows;const reportRows=all.filter(r=>r.market===dialog.querySelector('#export-market').value&&r.commodity_type===dialog.querySelector('#export-category').value);const d=latest(reportRows);return reportRows.filter(r=>r.report_date===d);}
 function update(){const report=scope()==='report',rs=rows();dialog.querySelector('#export-report-fields').hidden=!report;dialog.querySelector('#export-report-date').textContent=rs.length?'Latest available report: '+date(latest(rs)):'No available report for this market and category.';dialog.querySelector('#export-summary').textContent=`${groups(rs).length} commodities · ${rs.length} price lines`;dialog.querySelector('#export-csv').disabled=!rs.length;dialog.querySelector('#export-print').disabled=!rs.length;}
 dialog.onchange=update;dialog.querySelector('#close-export').onclick=()=>dialog.close();dialog.addEventListener('close',()=>dialog.remove(),{once:true});
 dialog.querySelector('#export-csv').onclick=()=>{const rs=rows(),blob=new Blob([exportCSV(rs)],{type:'text/csv;charset=utf-8;'}),href=URL.createObjectURL(blob),a=document.createElement('a');a.href=href;a.download='agrax-'+(scope()==='report'?dialog.querySelector('#export-market').value:route.market||'markets').toLowerCase().replace(/[^a-z0-9]+/g,'-')+'-'+(latest(rs)||'prices')+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(href),1000);dialog.querySelector('#export-status').textContent=`CSV download started: ${rs.length} price lines.`;};
 dialog.querySelector('#export-print').onclick=()=>{const rs=rows();const title=scope()==='report'?dialog.querySelector('#export-market').value+' · '+cats[dialog.querySelector('#export-category').value]:description;dialog.close();printExplorerRows(rs,title);};
 update();dialog.showModal();
}
function printExplorerRows(rows,title){
 document.querySelector('#explorer-print-document')?.remove();
 const print=document.createElement('section');print.id='explorer-print-document';
 print.innerHTML=`<img src="/assets/agrax-logo-ink.png" alt="AgraX" width="100"><h1>${E(title)}</h1><p>${groups(rows).length} commodities · ${rows.length} price lines · Exported ${E(new Date().toLocaleDateString('en-US'))}</p><p>USD per reported package. Dates and source reports are shown with each quote. Source: USDA AMS Market News. AgraX is independent and is not affiliated with USDA.</p>${groups(rows).map(([name,rs])=>`<h2>${E(name)}</h2><table><thead><tr><th>Market / report</th><th>Variety / origin</th><th>Package / size</th><th>Grade / notes</th><th>Reported price</th></tr></thead><tbody>${rs.map(r=>`<tr><td>${E(r.market)}<small>${E(date(r.report_date))}<br>${E(r.source_report||'USDA AMS')}</small></td><td>${E(Q.unique([r.variety,r.properties,r.organic?'Organic':''])||'Not supplied')}<small>${E(r.origin||'Not supplied')}</small></td><td>${E(r.package||'Not supplied')}<small>${E(r.size||'Not supplied')}</small></td><td>${E(r.grade||'—')}<small>${E(Q.qualifiers(r))}</small></td><td>${E(r.price_qualifier||'')} ${E(range(r))}${r.price_mostly_low!=null||r.price_mostly_high!=null?`<small>Mostly ${E(range({price_low:r.price_mostly_low,price_high:r.price_mostly_high}))}</small>`:''}</td></tr>`).join('')}</tbody></table>`).join('')}`;
 document.body.append(print);document.body.classList.add('printing-explorer');
 const cleanup=()=>{document.body.classList.remove('printing-explorer');print.remove();window.removeEventListener('afterprint',cleanup);};window.addEventListener('afterprint',cleanup);try{window.print();}catch{cleanup();toast('Printing is unavailable in this browser. Download CSV instead.');}
}
function pager(n){return `<div class="pagination"><span>${n?page*30+1:0}–${Math.min(page*30+30,n)} of ${n}</span><div><button data-page="-1" ${!page?'disabled':''}>← Previous</button><button data-page="1" ${page*30+30>=n?'disabled':''}>Next →</button></div></div>`;}
function bindPager(fn){document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{page+=Number(b.dataset.page);fn();window.scrollTo(0,0);});}
function product(){const base=all.filter(r=>r.commodity===route.c);if(!base.length){$('#content').innerHTML=empty('Product not found','Choose a commodity from the price explorer.',btn('Explore prices',url('explore')));return;}const fields=['market','variety','origin','package','size'];const values={market:route.market||'',...filter};const rs=base.filter(r=>fields.every(f=>!values[f]||r[f]===values[f]));page=Math.min(page,Math.max(0,Math.ceil(rs.length/30)-1));$('#content').innerHTML='<div class="product-view">'+crumbs([['Overview',url('home')],['Explore prices',url('explore',{market:route.market})],[route.c]])+head('COMMODITY',route.c,`${unique(base.map(r=>r.market)).length} markets · ${base.length} specifications. Choose an exact quote to explore history and comparisons.`,`<button class="btn light" id="save-product">${A?.has(route.c)?'Saved ✓':'Save product +'}</button>`)+`<div class="spec-filters"><details class="product-refine"><summary>Filters (${fields.slice(1).filter(f=>values[f]).length}) <span>☷</span></summary><div class="product-refine-fields">${fields.map((f,i)=>`<label class="spec-${f}">${['Market','Variety','Origin','Package','Size'][i]}<select data-filter="${f}"><option value="">All ${f==='variety'?'varieties':f==='market'?'markets':f==='origin'?'origins':f==='size'?'sizes':'packages'}</option>${unique(base.filter(r=>fields.every(k=>k===f||!values[k]||r[k]===values[k])).map(r=>r[f])).sort().map(v=>`<option ${values[f]===v?'selected':''}>${E(v)}</option>`).join('')}</select></label>`).join('')}<button id="clear-spec">Clear filters</button></div></details></div><div class="product-results-count">${rs.length} ${rs.length===1?'quote':'quotes'}${values.origin?' · '+E(values.origin):''}${values.variety?' · '+E(values.variety):''}</div><div class="table-box product-table"><table class="data-table"><thead><tr><th>Variety / origin</th><th>Pack / size</th><th class="hide-mobile">Market / date</th><th>Reported price</th></tr></thead><tbody>${rs.slice().sort(Q.compareQuotes).slice(page*30,page*30+30).map(r=>`<tr><td><a href="${E(url('quote',{id:r.row_hash,c:r.commodity,market:r.market}))}">${E(r.variety||'Variety not supplied')}</a><small>${E(r.origin||'Origin not supplied')}</small></td><td class="quote-pack-cell"><div class="quote-pack-line"><span>${E(r.package||'Package not supplied')}</span><span class="quote-size"><span class="quote-size-label">Size</span> ${E(r.size||'Not supplied')}</span></div><small class="quote-grade">${E(r.grade||'Grade not supplied')}</small><small class="quote-notes">${E(Q.qualifiers(r))}</small></td><td class="hide-mobile">${E(r.market)}<small>${E(date(r.report_date))}</small></td><td class="numeric"><a href="${E(url('quote',{id:r.row_hash,c:r.commodity,market:r.market}))}">${E(range(r))} ↗</a><small>${E(r.market)} · ${E(date(r.report_date))}</small></td></tr>`).join('')}</tbody></table>${!rs.length?empty('No matching specifications','Reset a filter to see more quotes.'):''}</div>${pager(rs.length)}<p class="notice">USD per reported package. “Mostly” prices, qualifiers, and full specifications are available inside each quote.</p></div>`;const marketLabel=$('.spec-market');$('.spec-filters').prepend(marketLabel);$('.product-refine').open=matchMedia('(min-width:601px)').matches;document.querySelectorAll('[data-filter]').forEach(el=>el.onchange=()=>{filter[el.dataset.filter]=el.value;page=0;history.replaceState(null,'',url('product',{c:route.c,market:route.market,...Object.fromEntries(Object.entries(filter).map(([k,v])=>['f_'+k,v||'__all__']))}));product();});$('#clear-spec').onclick=()=>{filter={market:''};page=0;history.replaceState(null,'',url('product',{c:route.c}));route.market='';product();};$('#save-product').onclick=()=>saveProduct(route.c);bindPager(product);}
async function saveProduct(c){if(!A?.user()){window.agraxAccountUI?.open('signup');return;}try{await A.toggle(c);toast(A.has(c)?'Product saved to your account':'Product removed');if(route.view==='product')product();if(route.view==='saved')saved();}catch{toast('Could not update your saved products. Please try again.');}}
async function refresh(m){if(updates.has(m)){toast('Checking for newer reports…');return;}updates.set(m,true);toast('Checking for newer reports…');try{const r=await fetch(AGRAX_API_BASE+'/reports/current?'+new URLSearchParams({market_type:'terminal',lookback_days:7,market:m}),{signal:AbortSignal.timeout(14000)});if(!r.ok)throw Error();const data=await r.json();if(!Array.isArray(data))throw Error();const valid=M.latest(data.filter(r=>r.market===m));if(valid.length){all=[...all.filter(r=>r.market!==m),...valid];failures.delete(m);render();toast('Market reports updated. Check publication dates.');}else toast('No newer reports were returned. Keeping the dated reports shown.');}catch{failures.add(m);toast('Update unavailable. Your dated reports remain available.');}finally{updates.delete(m);}}
function quote(){const q=all.find(r=>r.row_hash===route.id)||archived.get(route.id);if(!q&&!archiveMisses.has(route.id)){restoreQuote(route.id);return;}if(!q){$('#content').innerHTML=empty('This quote is not in the available reports','Browse current specifications to find the product again.',btn('Find specifications',url('product',{c:route.c||'Avocados',market:route.market})));return;}const id=renderId;$('#content').innerHTML='<div class="quote-view" data-mobile-panel="history">'+crumbs([['Explore prices',url('explore')],[q.commodity,url('product',{c:q.commodity,market:q.market})],['Quote details']])+`<section class="quote-overview"><div><span class="eyebrow">${E(q.market)} · ${E(date(q.report_date))}</span><h1>${E(q.variety||q.commodity)}${q.variety?' '+E(q.commodity):''}</h1><p>${E(Q.unique([q.origin,q.package,q.size]))}</p>${Q.qualifiers(q)?`<p class="quote-qualifiers">${E(Q.qualifiers(q))}</p>`:''}<div class="actions"><button class="btn light" id="save-quote">${A?.has(q.commodity)?'Saved ✓':'Save product +'}</button><button class="btn light" id="copy-quote">Copy link ↗</button>${btn('Source report ↗',url('report',{market:q.market,category:q.commodity_type,date:q.report_date}),'light')}</div></div><div class="quote-price"><small>Reported price range</small><strong>${E(range(q))}</strong><small>USD per ${E(q.package||'reported package')}</small>${q.price_mostly_low!=null||q.price_mostly_high!=null?`<small>Mostly ${E(range({price_low:q.price_mostly_low,price_high:q.price_mostly_high}))}</small>`:''}<small>${E(q.price_qualifier||'')}</small></div></section><nav class="quote-mobile-tabs" aria-label="Quote information"><button data-quote-panel="history" aria-pressed="true">History</button><button data-quote-panel="markets" aria-pressed="false">Compare markets</button><button data-quote-panel="spec" aria-pressed="false">Details</button></nav><div class="detail-grid"><section class="panel history-panel"><div class="section-bar"><h2>Price history</h2><div class="periods">${[[30,'1M'],[90,'3M'],[366,'1Y']].map(([n,t])=>`<button data-days="${n}" aria-label="${n===30?'One month':n===90?'Three months':'One year'}" aria-pressed="${historyDays===n}" class="${historyDays===n?'active':''}">${t}</button>`).join('')}</div></div><div id="history-chart" aria-live="polite"><div class="initial-shell" style="height:240px"></div><p class="chart-note">Retrieving matching report observations…</p></div></section><section class="panel specification-panel"><div class="section-bar"><h2>The specification</h2></div><dl class="spec-list">${['variety','origin','package','size','grade','quality','quality_note','condition','properties','appearance','notes','price_notes','organic'].filter(f=>['variety','origin','package','size','grade'].includes(f)||q[f]).map(f=>`<div><dt>${E(f.replaceAll('_',' '))}</dt><dd>${E(f==='organic'?(q[f]?'Organic':'Not specified'):String(q[f]||'Not supplied'))}</dd></div>`).join('')}</dl></section></div><section class="panel match-section"><div class="section-bar"><h2>Across markets</h2><span class="small-label">EXACT MATCHES ONLY</span></div><p class="chart-note">Same variety, origin, package, size, grade, and other reported attributes. Same date: ${E(date(q.report_date))}.</p>${comparison(q)}</section><p class="notice">Source: ${E(q.source_report||'USDA AMS')}. Reported prices describe a specific product and package, not a market-wide average.</p></div>`;document.querySelectorAll('[data-quote-panel]').forEach(b=>b.onclick=()=>{$('.quote-view').dataset.mobilePanel=b.dataset.quotePanel;document.querySelectorAll('[data-quote-panel]').forEach(t=>t.setAttribute('aria-pressed',String(t===b)));});$('#save-quote').onclick=()=>saveProduct(q.commodity);$('#copy-quote').onclick=async()=>{try{await navigator.clipboard.writeText(location.href);toast('Link copied');}catch{toast('Copy the address from your browser.');}};document.querySelectorAll('[data-days]').forEach(b=>b.onclick=()=>{historyDays=Number(b.dataset.days);document.querySelectorAll('[data-days]').forEach(x=>(x.classList.toggle('active',x===b),x.setAttribute('aria-pressed',String(x===b))));drawHistory(q,id);});drawHistory(q,id);}
function comparison(q){const matches=M.matches(all,q).filter(r=>M.midpoint(r)!==null);if(!matches.length)return empty('No equivalent quote in another market','The available reports do not contain an exact match on this date. We keep different packs, sizes, and grades separate.',btn('Browse other specifications',url('product',{c:q.commodity}),'light'));const rs=[q,...matches],max=Math.max(1,...rs.map(r=>Number(r.price_high)||0));return `<div class="table-box"><table class="data-table"><thead><tr><th>Market</th><th>Reported range</th><th class="hide-mobile">Low–high · shared scale from $0</th><th></th></tr></thead><tbody>${rs.map(r=>`<tr><td>${E(r.market)}${r===q?'<small>Selected market</small>':''}</td><td class="numeric">${E(range(r))}</td><td class="hide-mobile"><span class="range-bar"><i style="left:${Number(r.price_low)/max*95}%;width:${Math.max(.7,(Number(r.price_high)-Number(r.price_low))/max*95)}%"></i></span></td><td>${r===q?'':`<a href="${E(url('quote',{id:r.row_hash,c:r.commodity,market:r.market}))}" aria-label="Open ${E(r.market)} quote">↗</a>`}</td></tr>`).join('')}</tbody></table></div>`;}
async function getHistory(q){if(historyCache.has(q.row_hash))return historyCache.get(q.row_hash);if(!historyPromises.has(q.row_hash))historyPromises.set(q.row_hash,(async()=>{let payload=snapshot.histories?.[q.row_hash];if(!payload){const r=await fetch(AGRAX_API_BASE+'/history?'+new URLSearchParams({quote_id:q.row_hash,days:366}),{signal:AbortSignal.timeout(14000)});if(!r.ok)throw Error();payload=await r.json();}const series=M.series(payload,q);historyCache.set(q.row_hash,series);return series;})().finally(()=>historyPromises.delete(q.row_hash)));return historyPromises.get(q.row_hash);}
async function drawHistory(q,id){try{const observations=await getHistory(q);if(id!==renderId||route.id!==q.row_hash)return;const end=Date.parse(q.report_date),start=end-historyDays*864e5,ps=observations.filter(p=>Date.parse(p.report_date)>=start);if(!ps.length){$('#history-chart').innerHTML=empty('No observations in this period','Choose a longer period. Only matching specifications are included.');return;}const chartWidth=matchMedia('(max-width:600px)').matches?360:660,plotWidth=chartWidth-95;const min=Math.max(0,Math.min(...ps.map(p=>Number(p.price_low)))-2),max=Math.max(...ps.map(p=>Number(p.price_high)))+2,first=Date.parse(ps[0].report_date),x=p=>52+(end===first?plotWidth/2:(Date.parse(p.report_date)-first)/(end-first)*plotWidth),y=v=>214-(v-min)/(max-min)*175;$('#history-chart').innerHTML=`<svg class="chart" viewBox="0 0 ${chartWidth} 260" role="img" aria-label="Reported low and high prices by date">${[0,1,2,3,4].map(i=>`<line x1="52" x2="${chartWidth-43}" y1="${39+i*43.75}" y2="${39+i*43.75}" stroke="#e5eae5"/><text x="0" y="${43+i*43.75}">${money(max-(max-min)*i/4)}</text>`).join('')}${ps.map(p=>`<g><title>${E(p.report_date)}: ${range(p)}</title><line x1="${x(p)}" x2="${x(p)}" y1="${y(p.price_low)}" y2="${y(p.price_high)}" stroke="#176340" stroke-width="5" stroke-linecap="round"/><circle cx="${x(p)}" cy="${y(p.price_low)}" r="3" fill="#176340"/><circle cx="${x(p)}" cy="${y(p.price_high)}" r="3" fill="#176340"/></g>`).join('')}<text x="52" y="245">${E(date(ps[0].report_date))}</text><text x="${chartWidth-43}" y="245" text-anchor="end">${E(date(q.report_date))}</text></svg><p class="chart-note">${ps.length} observations · USD / package · Through ${E(date(q.report_date))}</p><details class="history-data"><summary>Prices & chart notes</summary><p class="chart-note">Each mark shows the reported low–high range for this exact specification. Unreported dates are not filled in.</p><div class="table-box"><table class="data-table"><thead><tr><th>Report date</th><th>Low</th><th>High</th></tr></thead><tbody>${ps.slice().reverse().map(p=>`<tr><td>${E(date(p.report_date))}</td><td>${money(p.price_low)}</td><td>${money(p.price_high)}</td></tr>`).join('')}</tbody></table></div></details>`;}catch{if(id!==renderId)return;$('#history-chart').innerHTML=empty('History is temporarily unavailable','Your selected quote is still available. Try loading its history again.','<button class="btn light" id="retry-history">Retry history</button>');$('#retry-history').onclick=()=>drawHistory(q,id);}}
function reportGroups(){const map=new Map();all.forEach(r=>{const k=r.market+'|'+r.commodity_type;if(!map.has(k)||map.get(k).report_date<r.report_date)map.set(k,r);});return [...map.values()].filter(r=>(!route.market||route.market===r.market)&&(!route.category||route.category===r.commodity_type)).sort((a,b)=>cities.indexOf(a.market)-cities.indexOf(b.market)||a.commodity_type.localeCompare(b.commodity_type));}
function reports(){const list=reportGroups();$('#content').innerHTML=head('REPORT LIBRARY','The source. All in one place.','Open a dated market report, print it, or save it as a PDF.',btn('Get these by email ↗',url('email'),'dark'))+`<form class="toolbar" id="report-filters"><label>Terminal market<select name="market"><option value="">All markets</option>${cities.map(c=>`<option ${route.market===c?'selected':''}>${c}</option>`).join('')}</select></label><label>Report category<select name="category"><option value="">All categories</option>${Object.entries(cats).map(([k,v])=>`<option value="${k}" ${route.category===k?'selected':''}>${v}</option>`).join('')}</select></label><span class="count">${list.length} reports available</span></form><div class="report-grid">${list.map(r=>`<article class="report-card"><div class="report-symbol">▤</div><span class="small-label">${E(cats[r.commodity_type]||r.commodity_type)}</span><h3>${E(r.market)}</h3><small>${E(date(r.report_date))} · ${E(r.source_report||'USDA AMS')}</small><a href="${E(url('report',{market:r.market,category:r.commodity_type,date:r.report_date}))}">Open report <span>↗</span></a></article>`).join('')}</div>${!list.length?empty('No reports match','Choose another market or category.'):''}<p class="notice">Publication dates differ by category. These are the latest reports in the available dataset.</p>`;$('#report-filters').onchange=()=>go('reports',Object.fromEntries(new FormData($('#report-filters'))));}
function openReportPrint(){
 const sections=[...document.querySelectorAll('.report-commodity')];
 if(!sections.length)return;
 document.querySelector('#report-print-dialog')?.remove();
 const dialog=document.createElement('dialog');dialog.id='report-print-dialog';dialog.setAttribute('aria-labelledby','print-title');
 const selected=new Set(sections.filter(s=>!s.hidden).map(s=>s.dataset.commodity));
 const partial=selected.size!==sections.length;
 dialog.innerHTML=`<form method="dialog"><div class="print-dialog-heading"><h2 id="print-title">Choose what to print</h2><button aria-label="Close print options" value="cancel">✕</button></div><p class="notice">${E(route.market)} · ${E(cats[route.category])} · ${E(date(route.date||sections[0].closest('.report-document').querySelector('.report-metadata span:nth-child(2)').textContent))}</p><div class="print-modes"><label><input type="radio" name="print-mode" value="all" ${partial?'':'checked'}> Entire report</label><label><input type="radio" name="print-mode" value="selected" ${partial?'checked':''}> Selected commodities</label></div><div id="print-pick" ${partial?'':'hidden'}><input type="search" id="print-search" aria-label="Search commodities to print" placeholder="Search commodities"><div class="print-select-actions"><button type="button" id="print-all">Select all</button><button type="button" id="print-clear">Clear</button><span id="print-count" role="status"></span></div><div class="print-options">${sections.map((s,i)=>`<label><input type="checkbox" value="${i}" ${partial&&selected.has(s.dataset.commodity)?'checked':''}><span>${E(s.dataset.commodity)}</span><small>${s.dataset.lines} prices</small></label>`).join('')}</div></div><p class="notice">Includes market, date, source, and price notes. Choose Save as PDF in the print window.</p><div class="print-dialog-actions"><button type="button" class="btn light" id="preview-print">Preview selection</button><button type="button" class="btn" id="confirm-print">Print entire report</button></div></form>`;
 document.body.append(dialog);
 const boxes=[...dialog.querySelectorAll('.print-options input')];
 const mode=()=>dialog.querySelector('[name="print-mode"]:checked').value;
 function update(){const count=boxes.filter(b=>b.checked).length;dialog.querySelector('#print-pick').hidden=mode()==='all';dialog.querySelector('#print-count').textContent=count+' selected';dialog.querySelector('#confirm-print').textContent=mode()==='all'?'Print entire report':`Print ${count} ${count===1?'commodity':'commodities'}`;dialog.querySelector('#confirm-print').disabled=mode()!=='all'&&!count;dialog.querySelector('#preview-print').disabled=mode()!=='all'&&!count;}
 dialog.onchange=update;
 dialog.querySelector('#print-all').onclick=()=>{boxes.forEach(b=>b.checked=true);update();};
 dialog.querySelector('#print-clear').onclick=()=>{boxes.forEach(b=>b.checked=false);update();};
 dialog.querySelector('#print-search').oninput=e=>{const term=e.target.value.trim().toLowerCase();boxes.forEach((b,i)=>b.closest('label').hidden=!sections[i].dataset.commodity.toLowerCase().includes(term));};
 function apply(){let count=0,lines=0;sections.forEach((s,i)=>{s.hidden=mode()!=='all'&&!boxes[i].checked;if(!s.hidden){count++;lines+=Number(s.dataset.lines);}});$('#report-commodity-count').textContent=count+' commodities';$('#report-line-count').textContent=lines+' price lines';$('#report-print-selection')?.remove();if(count<sections.length){const note=document.createElement('div');note.id='report-print-selection';note.innerHTML=`<span>Print preview: ${count} of ${sections.length} commodities</span><button type="button">Show full report</button>`;$('#report-content').before(note);note.querySelector('button').onclick=()=>{sections.forEach(s=>s.hidden=false);$('#report-commodity-count').textContent=sections.length+' commodities';$('#report-line-count').textContent=sections.reduce((n,s)=>n+Number(s.dataset.lines),0)+' price lines';note.remove();};}dialog.close();}
 dialog.querySelector('#preview-print').onclick=()=>{apply();$('#print-report').focus();};
 dialog.querySelector('#confirm-print').onclick=()=>{apply();window.print();};
 dialog.addEventListener('close',()=>dialog.remove(),{once:true});update();dialog.showModal();
}
async function report(){const m=route.market,c=route.category,d=route.date||latest(all.filter(r=>r.market===route.market&&r.commodity_type===route.category)),id=renderId;if(!cities.includes(m)||!cats[c]||!/^\d{4}-\d{2}-\d{2}$/.test(d||'')){notFound();return;}$('#content').innerHTML=crumbs([['Report library',url('reports')],[m,url('reports',{market:m})],[date(d)]])+head('DATED MARKET REPORT',m+' · '+cats[c],E(date(d)),`<div class="actions report-actions">${btn("Explore latest prices →",url("explore",{market:m,category:c}))}<button class="btn light" id="print-report" disabled>Print / Save PDF ↗</button></div>`)+`<p class="report-explore-note">Filter ${E(m)} ${E(cats[c].toLowerCase())} prices, view price history, and compare markets. Explore prices shows the latest available reports; this report stays dated ${E(date(d))}.</p><section class="report-document" id="report-content"><div class="initial-shell"></div><p class="notice">Retrieving the complete dated report…</p></section>`;$('#print-report').onclick=()=>openReportPrint();let rs=all.filter(r=>r.market===m&&r.commodity_type===c&&r.report_date===d);if(!rs.length){try{const data=await agraxAPI.reportTerminal(d);rs=data.filter(r=>r.market===m&&r.commodity_type===c&&r.report_date===d);}catch{if(id===renderId)$('#report-content').innerHTML=empty('Report unavailable','We could not retrieve this dated report. Please try again.','<button class="btn light" id="report-retry">Retry</button>');$('#report-retry')?.addEventListener('click',report);return;}}if(id!==renderId)return;if(!rs.length){$('#report-content').innerHTML=empty('No report for this date','Return to the library to choose another publication.',btn('Report library',url('reports')));return;}rs.forEach(r=>{if(r.row_hash)archived.set(r.row_hash,r);});$('#print-report').disabled=false;$('#report-content').innerHTML=`<img src="/assets/agrax-logo-ink.png" alt="AgraX" width="100"><div class="report-metadata"><span>${E(m)} terminal market</span><span>${E(date(d))}</span><span id="report-commodity-count">${groups(rs).length} commodities</span><span id="report-line-count">${rs.length} price lines</span></div><p class="notice">USD per reported package. Quotes retain their reported size, origin, grade, and qualifiers. Source: ${E(unique(rs.map(r=>r.source_report)).join(', '))}. Independent presentation of USDA AMS data.</p>${groups(rs).sort((a,b)=>a[0].localeCompare(b[0])).map(([n,items])=>`<section class="report-commodity" data-commodity="${E(n)}" data-lines="${items.length}"><h2>${E(n)}</h2><div class="table-box"><table class="data-table"><thead><tr><th>Variety / origin</th><th>Package / size</th><th>Grade / notes</th><th>Price range</th></tr></thead><tbody>${items.sort(Q.compareQuotes).map(r=>`<tr><td>${r.row_hash?`<a class="report-quote-link" href="${E(url('quote',{id:r.row_hash,c:r.commodity,market:r.market}))}" aria-label="View ${E(r.commodity)} quote details: ${E(Q.unique([r.variety,r.origin,r.package,r.size]))}">${E(Q.unique([r.variety,r.properties,r.organic?'Organic':''])||'View quote')} <span class="report-link-arrow" aria-hidden="true">↗</span></a>`:E(Q.unique([r.variety,r.properties,r.organic?'Organic':''])||'Not supplied')}<small>${E(r.origin||'Not supplied')}</small></td><td>${E(r.package||'Not supplied')}<small>${E(r.size||'Not supplied')}</small></td><td>${E(r.grade||'—')}<small>${E(Q.qualifiers(r))}</small></td><td class="numeric">${E(r.price_qualifier||'')} ${E(range(r))}${r.price_mostly_low!=null||r.price_mostly_high!=null?`<small>Mostly ${E(range({price_low:r.price_mostly_low,price_high:r.price_mostly_high}))}</small>`:''}</td></tr>`).join('')}</tbody></table></div></section>`).join('')}`;}
function email(){ $('#content').innerHTML=`${crumbs([['Overview',url('home')],['Daily email reports']])}<div class="email-layout"><section class="email-story"><span class="eyebrow">YOUR DAILY MARKET ROUTINE</span><h1>Open your inbox.<br>Know your market.</h1><p>The reports you need, without the daily search. Choose your markets and categories. We’ll email new reports after publication.</p><img src="/assets/hero-field.png" alt="Sunlight over a green agricultural field" style="object-position:center 65%"><div class="steps">${[['01','Choose the markets you follow','One city or several. Pick the reports relevant to your business.'],['02','Confirm your email','Use the confirmation link we send to activate delivery.'],['03','Get newly published reports','Free. No account required. Unsubscribe whenever you like.']].map(([n,t,s])=>`<div class="step"><span>${n}</span><div><strong>${t}</strong><small>${s}</small></div></div>`).join('')}</div></section><section class="panel subscription-form"><h2>Make it your morning.</h2><p class="notice">Delivery follows report publication. There may be no email on weekends, holidays, or days without a new report.</p><form id="email-form"><label class="email-input">Your email address<input type="email" name="email" placeholder="you@company.com" autocomplete="email" required maxlength="254"></label><div class="section-bar"><h3>Select your reports</h3><span class="choice-count" id="choice-count">0 selected</span></div><div id="email-choices"></div><button class="btn dark" type="submit">Send my confirmation link ↗</button><p class="form-status" id="email-status" role="status"></p><p class="notice">Submitting requests a confirmation email. Delivery starts only after you confirm. <a href="${url('privacy')}">Privacy policy ↗</a></p></form><p class="email-manage">Already subscribed? <a href="${url('manage')}">Manage your reports</a></p></section></div>`;reportChoices.render($('#email-choices'));const fields=[...$('#email-choices').children];fields.forEach((f,i)=>{const legend=f.querySelector('legend').textContent;const detail=document.createElement('details');if(i===0)detail.open=true;const summary=document.createElement('summary');summary.textContent=legend;detail.append(summary,f);f.querySelector('legend').hidden=true;$('#email-choices').append(detail);});$('#email-choices').onchange=()=>$('#choice-count').textContent=reportChoices.read($('#email-choices')).length+' selected';$('#email-form').onsubmit=async e=>{e.preventDefault();const form=e.currentTarget,reports=reportChoices.read(form),status=$('#email-status'),button=form.querySelector('[type=submit]');if(!reports.length){status.textContent='Choose at least one report category.';return;}button.disabled=true;status.textContent='Sending your confirmation…';try{const r=await newsletterPost('request',{email:new FormData(form).get('email'),reports});if(!r.confirmation_required)throw Error('Confirmation is currently unavailable. Please try again.');status.textContent='Check your inbox. Confirm your email to activate your chosen reports.';}catch(error){status.textContent=error.message;}finally{button.disabled=false;}};}
async function manage(){const fragment=new URLSearchParams(location.hash.slice(1));let token=fragment.get('manage'),confirmToken=fragment.get('confirm');$('#content').innerHTML=head('EMAIL PREFERENCES','Your reports. Your choices.','Manage delivery with the private link sent to your inbox.')+`<section class="panel subscription-form" style="max-width:700px"><p id="manage-status" role="status">${token?'Retrieving your preferences…':confirmToken?'Confirm that you requested these report choices. This replaces any previous choices.':'Open the private management link in a report email to change your subscriptions or unsubscribe.'}</p><button class="btn" id="confirm-sub" ${confirmToken?'':'hidden'}>Confirm my report choices</button><form id="manage-form" hidden><div id="manage-choices"></div><button class="btn" type="submit">Save report choices</button><button class="btn light" type="button" id="unsubscribe">Unsubscribe from all reports</button></form>${!token&&!confirmToken?`<div class="actions">${btn('Request a new confirmation',url('email'))}</div>`:''}</section>`;async function load(){const r=await newsletterPost('preferences/read',{token});reportChoices.render($('#manage-choices'),r.reports);$('#manage-form').hidden=false;$('#manage-status').textContent=r.unsubscribed?'You are unsubscribed. Saving choices will not reactivate delivery.':r.delivery_enabled?'Your choices are confirmed. Newly published reports will be emailed to you.':'Your choices are confirmed. Daily delivery is not currently active.';$('#unsubscribe').disabled=r.unsubscribed;}if(token)try{await load();}catch(e){$('#manage-status').textContent=e.message;}$('#confirm-sub').onclick=async e=>{e.target.disabled=true;try{const r=await newsletterPost('confirm',{token:confirmToken});token=r.manage_token;history.replaceState(null,'',url('manage')+'#manage='+encodeURIComponent(token));e.target.hidden=true;await load();}catch(error){$('#manage-status').textContent=error.message;e.target.disabled=false;}};$('#manage-form').onsubmit=async e=>{e.preventDefault();const reports=reportChoices.read(e.currentTarget);if(!reports.length){$('#manage-status').textContent='Select a report or use Unsubscribe.';return;}const b=e.currentTarget.querySelector('[type=submit]');b.disabled=true;try{await newsletterPost('preferences',{token,reports});$('#manage-status').textContent='Your report choices have been saved.';}catch(error){$('#manage-status').textContent=error.message;}finally{b.disabled=false;}};$('#unsubscribe').onclick=async e=>{e.target.disabled=true;try{await newsletterPost('unsubscribe',{token});$('#manage-status').textContent='You are unsubscribed from all AgraX report emails.';}catch(error){$('#manage-status').textContent=error.message;e.target.disabled=false;}};}
function saved(){const names=A?.watch()||[];$('#content').innerHTML=head('YOUR WORKSPACE','Keep your products close.','Save the commodities you follow. Pick up your research from any device.',btn('Explore prices ↗',url('explore'),'light'))+(A?.watchError()?empty('Your watchlist could not load','Retry to retrieve your saved products.','<button class="btn" id="retry-watch">Retry</button>'):!A?.user()?`<section class="photo-band" style="margin-top:0"><img src="/assets/produce-hero.png" alt="Fresh produce ready for the wholesale market"><div><span class="eyebrow">YOUR PERSONAL SHORTLIST</span><h2>Less searching.<br>More of what matters.</h2><p>Sign in to save products and access your watchlist across devices. Report emails are a separate subscription.</p><button class="btn" id="saved-signin">Sign in / Create account ↗</button></div></section>`:!names.length?empty('Your shortlist starts here','Open a commodity and choose Save product. Your saved items will appear here.',btn('Find a product',url('explore'))):`<div class="saved-grid">${names.map(n=>`<article class="panel saved-card"><span class="eyebrow">SAVED COMMODITY</span><h3>${E(n)}</h3><small>${unique(all.filter(r=>r.commodity===n).map(r=>r.market)).length} markets in available reports</small><div class="actions">${btn('Explore ↗',url('product',{c:n}),'light')}<button data-remove="${E(n)}" aria-label="Remove ${E(n)}">Remove</button></div></article>`).join('')}</div>`);$('#saved-signin')?.addEventListener('click',()=>window.agraxAccountUI.open('login'));$('#retry-watch')?.addEventListener('click',()=>A.refreshWatch());document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>saveProduct(b.dataset.remove));}
function about(){ $('#content').innerHTML=`<section class="about-hero"><div><span class="eyebrow">ABOUT AGRAX</span><h1>Clarity for the people<br>behind the produce.</h1><p>AgraX makes USDA wholesale produce reports easier to find, understand, and use. Built for buyers, growers, shippers, and anyone who needs a clearer view of the market.</p>${btn('Explore the data ↗',url('explore'))}</div><img src="/assets/account-warehouse.jpg" alt="People working among crates at a produce warehouse"></section><div class="principles">${[['01','Source first','Our price information comes from USDA Agricultural Marketing Service reports. Source reports and publication dates stay visible.'],['02','Details matter','Variety, origin, package, size, grade, and condition define the quote. We preserve those differences instead of hiding them in an average.'],['03','Made to be useful','Explore products, inspect reported history, compare equivalent quotes, and receive reports by email. Public price browsing is free.']].map(([n,t,p])=>`<section class="panel"><span class="eyebrow">${n}</span><h3>${t}</h3><p>${p}</p></section>`).join('')}</div><section class="panel faq"><div class="section-bar"><h2>Understand what you’re seeing.</h2></div>${[['Are these live prices?','No. Prices come from dated USDA publications. Publication schedules differ by market and category. Always check the report date before using a quote.'],['What does the price range mean?','The low and high are the reported range for the specified product and package. They are not converted to a per-pound price. “Mostly” values appear only where the source reports them.'],['How are other markets compared?','AgraX requires matching specifications and the same report date. Different varieties, origins, packages, sizes, grades, or reported attributes are not presented as equivalent quotes.'],['How does price history work?','History includes matching observations for the same market and specification, up to one year where available. Missing dates are not filled in, and the selected period ends on the quote’s report date.'],['Do I need an account for email reports?','No. Choose your reports on the Daily email reports page and confirm your email. Creating an account alone does not subscribe you to report delivery.'],['Is AgraX part of the USDA?','No. AgraX is an independent presentation of USDA AMS data and is not affiliated with or endorsed by USDA.']].map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')}</section><section class="email-band"><div><h2>A useful start to your day.</h2><p>Pick your markets once. Receive newly published reports by email.</p></div>${btn('Set up report emails ↗',url('email'))}</section>`;}
function privacy(){$('#content').innerHTML=`<article class="prose">${window.AGX_PRIVACY||'<h1>Privacy policy</h1><p>Policy could not load. Please reload.</p>'}</article>`;$('#content').querySelectorAll('a').forEach(a=>{if(a.getAttribute('href')==='https://www.agra-x.com/')a.href=url('home');});}

async function restoreQuote(id){
 const version=renderId;$('#content').innerHTML=empty('Opening your saved quote','Retrieving the original dated specification…');
 try{const r=await fetch(AGRAX_API_BASE+'/history?'+new URLSearchParams({quote_id:id,days:366}),{signal:AbortSignal.timeout(14000)});if(!r.ok)throw Error();const payload=await r.json();const q=payload.observations?.find(q=>q.row_hash===id);if(!q)throw Error();archived.set(id,q);historyCache.set(id,M.series(payload,q));}
 catch{archiveMisses.add(id);}if(version===renderId&&route.id===id)quote();
}
function readMarketCache(){for(const m of cities){try{const item=JSON.parse(localStorage.getItem('agrax-workspace-market:'+m)||'null');if(item&&Array.isArray(item.rows)&&item.at>Date.parse(snapshot.generated_at)){all=[...all.filter(r=>r.market!==m),...M.latest(item.rows)];}}catch{}}}
async function backgroundUpdates(){
 let index=0;
 async function worker(){while(index<cities.length){const market=cities[index++];let last=Date.parse(snapshot.generated_at)||0;try{last=Math.max(last,JSON.parse(localStorage.getItem('agrax-workspace-market:'+market)||'null')?.at||0);}catch{}if(Date.now()-last<300000)continue;
 try{const r=await fetch(AGRAX_API_BASE+'/reports/current?'+new URLSearchParams({market_type:'terminal',lookback_days:7,market}),{signal:AbortSignal.timeout(14000)});if(!r.ok)throw Error();const payload=await r.json();if(!Array.isArray(payload))throw Error();const rows=M.latest(payload.filter(r=>r.market===market));if(!rows.length)continue;all=[...all.filter(r=>r.market!==market),...rows];try{localStorage.setItem('agrax-workspace-market:'+market,JSON.stringify({rows,at:Date.now()}));}catch{}
 }catch{/* Keep the dated bundled reports available during a failed update. */}
 }
 }
 await Promise.all([worker(),worker()]);
 if(['home','explore','reports','product'].includes(route.view)&&!document.activeElement?.matches('input,select,button')){const y=window.scrollY;render();window.scrollTo(0,y);}
}

function notFound(){$('#content').innerHTML=empty('Let’s get you back to the market.','This page could not be found.',btn('Go to overview',url('home')));}
document.addEventListener('click',e=>{if(!e.target.closest('a,button,input,select')){const link=e.target.closest('.data-table tbody tr')?.querySelector('a');if(link){link.click();return;}}const a=e.target.closest('a');if(!a||e.ctrlKey||e.metaKey||e.shiftKey||e.altKey||e.button>0||a.target==='_blank')return;const target=new URL(a.href,location.href);if(target.origin===location.origin&&target.pathname==='/'&&target.searchParams.has('view')&&!target.hash){e.preventDefault();history.pushState(null,'',target.href);page=0;filter={};render();window.scrollTo(0,0);}});
$('#global-search').onsubmit=e=>{e.preventDefault();const q=new FormData(e.target).get('q').trim();if(!q){go('explore');return;}const market=cities.find(c=>c.toLowerCase()===q.toLowerCase());go('explore',market?{market}:{q});};$('#account-button').onclick=()=>window.agraxAccountUI?.open(A?.user()?'settings':'login');$('#mobile-menu').onclick=()=>{const open=document.body.classList.toggle('menu-open');$('#mobile-menu').setAttribute('aria-expanded',String(open));};window.addEventListener('popstate',()=>{page=0;filter={};render();});document.addEventListener('keydown',e=>{if(e.key==='Escape'){document.body.classList.remove('menu-open');$('#mobile-menu').setAttribute('aria-expanded','false');}});if(location.hash.startsWith('#manage=')||location.hash.startsWith('#confirm='))history.replaceState(null,'',url('manage')+location.hash);readMarketCache();render();backgroundUpdates();A?.onChange(()=>{nav();if(route.view==='saved')saved();});
})();
